# Стритлифтинг (Calisthetics) и кроссфит (Phil Team): списки, запуск, история.
# Запуск: python3 tests/street_cf_check.py index.html [папка_скриншотов]
import asyncio,json,os,sys,shutil,tempfile,http.server,threading,functools
from playwright.async_api import async_playwright
HTML=os.path.abspath(sys.argv[1]);SHOT=sys.argv[2] if len(sys.argv)>2 else None
tmp=tempfile.mkdtemp();shutil.copy(HTML,tmp+'/index.html')
if os.path.isdir(os.path.dirname(HTML)+'/media'):os.symlink(os.path.dirname(HTML)+'/media',tmp+'/media')
srv=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(type('Q',(http.server.SimpleHTTPRequestHandler,),{'log_message':lambda *a:None}),directory=tmp))
threading.Thread(target=srv.serve_forever,daemon=True).start();URL=f'http://127.0.0.1:{srv.server_address[1]}/index.html'
R=[]
def ok(n,c,x=''):R.append(bool(c));print(('PASS ' if c else 'FAIL ')+n+(' · '+str(x) if x!='' else ''))
async def m():
  async with async_playwright() as p:
    b=await p.chromium.launch();pg=await b.new_page(viewport={'width':390,'height':844},device_scale_factor=2);errs=[];pg.on('pageerror',lambda e:errs.append(str(e)))
    await pg.goto(URL);await pg.wait_for_timeout(300);await pg.evaluate("el('login').style.display='none';show('programs')");await pg.wait_for_timeout(100)
    await pg.evaluate("document.querySelector('.disc[data-disc=\"Стритлифтинг\"]').click()");await pg.wait_for_timeout(120)
    ok('стритлифтинг: классический цикл одной программой + Level Zero + 4 программы',await pg.evaluate("currentScreen==='street'&&el('streetDays').querySelector('.disc').textContent.includes('Классический цикл')&&STREET_PROGS.length===4&&el('streetDays').querySelectorAll('.disc').length===8"))
    await pg.evaluate("document.querySelector('.disc[data-disc=\"Стритлифтинг\"]')&&(show('programs'),document.querySelector('.disc[data-disc=\"Стритлифтинг\"]').click())");await pg.wait_for_timeout(120)
    ok('повторное открытие не дублирует список',await pg.evaluate("el('streetDays').querySelectorAll('.disc').length===8"))
    if SHOT:await pg.screenshot(path=SHOT+'/street.png',full_page=True)
    await pg.evaluate("[...el('streetDays').querySelectorAll('.disc')].find(b=>b.textContent.includes('Метод 5×5')).click()");await pg.wait_for_timeout(120)
    ok('5×5: 4 тренировки',await pg.evaluate("el('bodyDays').querySelectorAll('.disc').length===4"))
    await pg.evaluate("el('bodyDays').querySelectorAll('.disc')[2].click()");await pg.wait_for_timeout(100);await pg.evaluate("el('dayStart').click()");await pg.wait_for_timeout(150)
    ok('сессия B: своя строка цели',await pg.evaluate("el('exList').querySelector('.target').textContent.includes('5-5-5-5-3')"))
    await pg.evaluate("current.sets.forEach(se=>se.forEach(s=>{s.done=true;}));finishWorkout()");await pg.wait_for_timeout(150)
    ok('история: раздел street',await pg.evaluate("safe.get().slice(-1)[0].sec==='street'"))
    ok('комплекс 1 — суперсет подтягивания → брусья',await pg.evaluate("(()=>{const d=STREET_PROGS[3].days[0];current={program:{ex:d.ex}};const g=wkGroup(0);current=null;return g&&g.join()==='0,1'})()"))
    ok('Блатов: 8 тренировок 5×2…5×5',await pg.evaluate("STREET_PROGS[2].days.length===8&&STREET_PROGS[2].days.map(d=>d.ex[0][2]).join()==='2,2,3,3,4,4,5,5'"))
    await pg.evaluate("show('programs');document.querySelector('.disc[data-disc=\"Кроссфит\"]').click()");await pg.wait_for_timeout(150)
    ok('кроссфит: кнопка программы на месяц',await pg.evaluate("currentScreen==='cross'&&!!el('cfProgBtn')&&el('crossDays').querySelectorAll('#cfProgBtn').length===1"))
    if SHOT:await pg.screenshot(path=SHOT+'/cross.png')
    await pg.evaluate("el('cfProgBtn').click()");await pg.wait_for_timeout(120)
    ok('Phil Team: 24 тренировки',await pg.evaluate("el('bodyDays').querySelectorAll('.disc').length===24"))
    ok('нет повторов блоков внутри дня',await pg.evaluate("CF_PROG.days.every(d=>new Set(d.ex.map(e=>e[0])).size===d.ex.length)"))
    await pg.evaluate("el('bodyDays').querySelectorAll('.disc')[0].click()");await pg.wait_for_timeout(100);await pg.evaluate("el('dayStart').click()");await pg.wait_for_timeout(150)
    ok('блок: время и круги в строке цели',await pg.evaluate("el('exList').querySelector('.target').textContent.includes('2 круга — отметь')"))
    if SHOT:await pg.screenshot(path=SHOT+'/cf-block.png')
    await pg.evaluate("current.sets.forEach(se=>se.forEach(s=>{s.done=true;}));finishWorkout()");await pg.wait_for_timeout(150)
    ok('история: раздел cross',await pg.evaluate("safe.get().slice(-1)[0].sec==='cross'"))
    # французские программы с неделями
    ok('данные: Streetlift 6×5, Powerbuild 6×6, Body-lifting 10×5',await pg.evaluate("[EXT_PROGS.slpp,EXT_PROGS.pbx2,EXT_PROGS.blft].map(p=>p.weeks.length+'x'+p.weeks[0].days.length).join()==='6x5,6x6,10x5'"))
    ok('нет повторов упражнений внутри дня',await pg.evaluate("Object.values(EXT_PROGS).every(p=>p.weeks.every(w=>w.days.every(d=>new Set(d.ex.map(e=>e[0])).size===d.ex.length)))"))
    await pg.evaluate("show('programs');document.querySelector('.disc[data-disc=\"Стритлифтинг\"]').click()");await pg.wait_for_timeout(120)
    await pg.evaluate("[...el('streetDays').querySelectorAll('.disc')].find(b=>b.textContent.includes('Body-lifting')).click()");await pg.wait_for_timeout(150)
    ok('Body-lifting: выбор из 10 недель',await pg.evaluate("el('auWk').querySelectorAll('button').length===10&&el('progEyebrow').textContent.startsWith('Стритлифтинг')"))
    if SHOT:await pg.screenshot(path=SHOT+'/bl.png')
    await pg.evaluate("[...el('bodyDays').querySelectorAll('.disc')].pop().click()");await pg.wait_for_timeout(100);await pg.evaluate("el('dayStart').click()");await pg.wait_for_timeout(150)
    await pg.evaluate("current.sets.forEach(se=>se.forEach(s=>{s.done=true;}));finishWorkout()");await pg.wait_for_timeout(150)
    ok('история: street + счётчик программы',await pg.evaluate("safe.get().slice(-1)[0].sec==='street'&&auCount('blft')===1"))
    await pg.evaluate("show('programs');document.querySelector('.disc[data-disc=\"Пауэрлифтинг\"]').click()");await pg.wait_for_timeout(150)
    ok('пауэрлифтинг: Powerbuild в списке',await pg.evaluate("[...el('pwrPrograms').querySelectorAll('.disc')].filter(b=>b.textContent.includes('Powerbuild')).length===1"))
    await pg.evaluate("[...el('pwrPrograms').querySelectorAll('.disc')].find(b=>b.textContent.includes('Powerbuild')).click()");await pg.wait_for_timeout(150)
    ok('Powerbuild: 6 недель, 6 дней',await pg.evaluate("el('auWk').querySelectorAll('button').length===6&&[...el('bodyDays').querySelectorAll('.disc')].filter(b=>b.textContent.includes('Powerbuild ·')).length===6"),await pg.evaluate("[...el('bodyDays').querySelectorAll('.disc')].map(b=>b.textContent.slice(0,30))"))
    await pg.evaluate("show('programs');document.querySelector('.disc[data-disc=\"Пауэрлифтинг\"]').click()");await pg.wait_for_timeout(150)
    ok('пауэрлифтинг: обе программы «Жим лёжа 180»',await pg.evaluate("[...el('pwrPrograms').querySelectorAll('.disc')].filter(b=>b.textContent.includes('Жим лёжа 180')).length===2"))
    ok('Жим 180: 3 программы + 8 этапов, без повторов в дне',await pg.evaluate("BP_BEG.weeks.length===3&&BP_ADV.weeks.length===8&&[BP_BEG,BP_ADV].every(p=>p.weeks.every(w=>w.days.length===3&&w.days.every(d=>new Set(d.ex.map(e=>e[0])).size===d.ex.length)))"))
    await pg.evaluate("[...el('pwrPrograms').querySelectorAll('.disc')].find(b=>b.textContent.includes('для опытных')).click()");await pg.wait_for_timeout(150)
    await pg.evaluate("[...el('auWk').querySelectorAll('button')][7].click()");await pg.wait_for_timeout(100)
    await pg.evaluate("[...el('bodyDays').querySelectorAll('.disc')].find(b=>b.textContent.includes('Ф5 · Пн')).click()");await pg.wait_for_timeout(100);await pg.evaluate("el('dayStart').click()");await pg.wait_for_timeout(150)
    ok('Ф5 нед. 4: жим на рекорд, без наклонного жима',await pg.evaluate("current.program.ex[0][0].includes('новый максимум')&&current.program.ex.length===2"))
    await pg.evaluate("current.sets.forEach(se=>se.forEach(s=>{s.done=true;}));finishWorkout()");await pg.wait_for_timeout(150)
    ok('история: раздел pwr',await pg.evaluate("safe.get().slice(-1)[0].sec==='pwr'&&auCount('bp180a')===1"))
    await pg.evaluate("localStorage.setItem('gym45_rm_v1',JSON.stringify({'Жим лёжа':125}))")
    await pg.evaluate("show('programs');document.querySelector('.disc[data-disc=\"Пауэрлифтинг\"]').click()");await pg.wait_for_timeout(150)
    await pg.evaluate("[...el('pwrPrograms').querySelectorAll('.disc')].find(b=>b.textContent.includes('Фалеев')).click()");await pg.wait_for_timeout(150)
    ok('Фалеев: 22 этапа, без повторов в дне',await pg.evaluate("el('auWk').querySelectorAll('button').length===22&&FAL_PROG.weeks.every(w=>w.days.every(d=>new Set(d.ex.map(e=>e[0])).size===d.ex.length))"))
    ok('Фалеев: веса от 1ПМ (жим 125 → 5×5 105, финал 125)',await pg.evaluate("FAL_PROG.weeks[8].days[1].ex[0][3]===105&&FAL_PROG.weeks[21].days[1].ex[0][3]===125&&FAL_PROG.weeks[2].days[1].ex[0][3]===90"),await pg.evaluate("[FAL_PROG.weeks[8].days[1].ex[0][3],FAL_PROG.weeks[21].days[1].ex[0][3],FAL_PROG.weeks[2].days[1].ex[0][3]]"))
    await pg.evaluate("[...el('bodyDays').querySelectorAll('.disc')].pop().click()");await pg.wait_for_timeout(100);await pg.evaluate("el('dayStart').click()");await pg.wait_for_timeout(150)
    await pg.evaluate("current.sets.forEach(se=>se.forEach(s=>{s.done=true;}));finishWorkout()");await pg.wait_for_timeout(150)
    ok('Фалеев: история pwr + счётчик',await pg.evaluate("safe.get().slice(-1)[0].sec==='pwr'&&auCount('faleev')===1"))
    ok('без горизонтальной прокрутки',await pg.evaluate("document.documentElement.scrollWidth<=innerWidth+1"))
    ok('ошибок JS нет',not errs,errs[:3])
    await b.close()
  print(f'\n{sum(R)}/{len(R)} PASS');sys.exit(0 if all(R) else 1)
asyncio.run(m())
